describe('Sauce Labs Backpack Checkout', () => {
  it('should complete the checkout process successfully', () => {
    cy.visit('https://www.saucedemo.com');
    cy.get('a[data-test="sign_in"]').click();
    cy.get('a[data-test="standard_user"]').click();
    cy.get('input[data-test="user_name"]').type('standard_user');
    cy.get('input[data-test="password"]').type('secret_sauce');
    cy.get('input[data-test="user_name"]').type('standard_user');
    cy.get('input[data-test="password"]').type('secret_sauce');
    cy.get('a[data-test="sign_in"]').click();
    cy.get('a[data-test="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('a[data-test="cart"]').click();
    cy.get('a[data-test="checkout"]').click();
    cy.get('input[data-test="firstName"]').type('Saif');
    cy.get('input[data-test="lastName"]').type('Afzal');
    cy.get('input[data-test="postalCode"]').type('201301');
    cy.get('input[data-test="continue"]').click();
    cy.url().should('include', '/checkout');
    cy.get('#itemTotal').should('be.visible');
    cy.get('a[data-test="finish"]').click();
    cy.url().should('include', '/checkout');
    cy.get('.complete-header').should('contain', 'Thank you for your order!');
  });

  it('should not complete the checkout process with empty fields', () => {
    cy.visit('https://www.saucedemo.com');
    cy.get('a[data-test="sign_in"]').click();
    cy.get('a[data-test="standard_user"]').click();
    cy.get('input[data-test="user_name"]').type('standard_user');
    cy.get('input[data-test="password"]').type('secret_sauce');
    cy.get('input[data-test="user_name"]').type('standard_user');
    cy.get('input[data-test="password"]').type('secret_sauce');
    cy.get('a[data-test="sign_in"]').click();
    cy.get('a[data-test="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('a[data-test="cart"]').click();
    cy.get('a[data-test="checkout"]').click();
    cy.get('input[data-test="firstName"]').should('be.visible');
    cy.get('input[data-test="lastName"]').should('be.visible');
    cy.get('input[data-test="postalCode"]').should('be.visible');
    cy.get('input[data-test="continue"]').click();
    cy.url().should('include', '/checkout');
    cy.get('#itemTotal').should('be.visible');
    cy.get('a[data-test="finish"]').click();
    cy.url().should('include', '/checkout');
    cy.get('.complete-header').should('contain', 'Thank you for your order!');
  });
});
